INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "欢欢去文具店买学习用品，买笔记本用去30元。欢欢还买了一支水笔（水笔每盒40元，每盒5支）。她一共用去多少元？按四步解决问题：①读题②分析（写出数量关系）③解答④检验。", "options": null}', '一共用去38元。数量关系：买笔记本用去的钱数+买一支水笔用去的钱数=一共用去的钱数；解答：30+40÷5=30+8=38（元）；检验：38−40÷5=38−8=30（元），30元正好是买笔记本用去的钱，正确。', '一支水笔的价钱：40÷5=8（元）（先除后加）；一共：30+8=38（元）。检验时用总钱数减去水笔钱应回到笔记本的30元。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.5"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "小华要用8幅装饰画来布置房间，平均每幅装饰画需要9元，小华自己只有50元。要买这些画还缺多少元？", "options": null}', '22元', '8幅共需：8×9=72（元）；还缺：72−50=22（元）。综合算式：8×9−50=22。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.5"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "三（2）班的学生平均分成6组。（1）如果每组发2套飞行棋，还剩余2套，那么一共有多少套飞行棋？", "options": null}', '14套', '6×2+2=14（套），一共 14 套飞行棋。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.5"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "三（2）班的学生平均分成6组。（2）如果每组发3个篮球，还缺少3个，那么一共有多少个篮球？", "options": null}', '15个', '6×3−3=15（个），一共有 15 个篮球。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.5"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "某校学生积极报名参加“小志愿者”活动。第一天有104人报名，第二天有187人报名。这两天报名的学生中男生有155人，女生有多少人？", "options": null}', '136人', '两天共报名：104+187=291（人）；女生：291−155=136（人）。综合算式：104+187−155=136。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.5"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "一根绳子长2米，第一次剪去18厘米，第二次剪去的长度是第一次的一半。这根绳子剪了两次后短了多少厘米？", "options": null}', '27厘米', '问“短了多少厘米”即求两次一共剪去多少：18+18÷2=18+9=27（厘米）。（2米是多余条件）', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.5"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "商场对散装糖果进行促销活动：单买1粒是2元，购买1袋（每袋5粒）只需8元。小海需要购买12粒这样的糖果，最少要花多少元？", "options": null}', '20元', '尽量买袋装更便宜：12粒=2袋(10粒)+2粒，2×8+2×2=16+4=20（元）；若 3 袋(15粒)要 24 元更贵且多买。所以最少花 20 元。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.5"]', NULL, 0);
